CREATE TABLE farms(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator')), active boolean NOT NULL DEFAULT true);
CREATE TABLE user_farms(user_id uuid REFERENCES users(id), farm_id text REFERENCES farms(id), PRIMARY KEY(user_id,farm_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX ON sessions(expires_at);
CREATE TABLE cows(id text PRIMARY KEY, farm_id text NOT NULL REFERENCES farms(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON cows(farm_id,id);
CREATE TABLE metric_definitions(code text PRIMARY KEY, name text NOT NULL, unit text NOT NULL, min_value double precision NOT NULL, max_value double precision NOT NULL);
INSERT INTO metric_definitions VALUES
('body_temperature_c','Температура тела','°C',20,50),('respiratory_rate_bpm','Частота дыхания','дых/мин',0,200),('heart_rate_bpm','Пульс','уд/мин',0,300),('activity_index','Активность','0–1',0,1),('steps_per_min','Шаги','шаг/мин',0,300),('rumen_ph','pH рубца','pH',0,14),('rumination_min_1h','Жвачка','мин/ч',0,60),('feed_intake_kg_1h','Потребление корма','кг/ч',0,50),('water_intake_l_1h','Потребление воды','л/ч',0,100);
CREATE TABLE sensors(id text PRIMARY KEY,cow_id text NOT NULL REFERENCES cows(id), metric_type text NOT NULL REFERENCES metric_definitions(code), UNIQUE(cow_id,metric_type));
CREATE TABLE simulations(id uuid PRIMARY KEY, farm_id text NOT NULL REFERENCES farms(id), state text NOT NULL CHECK(state IN ('created','starting','running','paused','completed','stopped','failed')), config jsonb NOT NULL, version integer NOT NULL DEFAULT 1, progress jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE simulation_commands(id uuid PRIMARY KEY, simulation_id uuid NOT NULL REFERENCES simulations(id), version integer NOT NULL, action text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(simulation_id,version));
CREATE TABLE sensor_measurements(event_id uuid PRIMARY KEY,simulation_id uuid NOT NULL REFERENCES simulations(id),cow_id text NOT NULL REFERENCES cows(id),sensor_id text NOT NULL REFERENCES sensors(id),metric_type text NOT NULL REFERENCES metric_definitions(code),value double precision NOT NULL, recorded_at timestamptz NOT NULL, received_at timestamptz NOT NULL,source text NOT NULL CHECK(source IN ('synthetic','replay')));
CREATE INDEX ON sensor_measurements(cow_id,metric_type,recorded_at DESC);
CREATE INDEX ON sensor_measurements(recorded_at);
CREATE TABLE cow_latest_state(LIKE sensor_measurements INCLUDING DEFAULTS);
ALTER TABLE cow_latest_state ADD PRIMARY KEY(cow_id,metric_type);
CREATE TABLE outbox_events(id uuid PRIMARY KEY,event_type text NOT NULL,payload jsonb NOT NULL,owner text NOT NULL,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON outbox_events(owner,created_at) WHERE published_at IS NULL;
CREATE TABLE manual_records(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('milkings','inspections','laboratory-results','body-condition-records','veterinary-examinations')),cow_id text NOT NULL REFERENCES cows(id),observed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,payload jsonb NOT NULL,idempotency_key text NOT NULL,UNIQUE(created_by,idempotency_key));
CREATE INDEX ON manual_records(cow_id,observed_at DESC);
CREATE TABLE manual_revisions(record_id uuid NOT NULL REFERENCES manual_records(id),version integer NOT NULL,payload jsonb NOT NULL,observed_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),reason text NOT NULL,PRIMARY KEY(record_id,version));
CREATE TABLE audit_log(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),action text NOT NULL,resource_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analysis_jobs(cow_id text NOT NULL REFERENCES cows(id),window_end timestamptz NOT NULL,completed_at timestamptz,attempts integer NOT NULL DEFAULT 0,last_error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(cow_id,window_end));
CREATE TABLE ml_predictions(id uuid PRIMARY KEY,cow_id text NOT NULL REFERENCES cows(id),window_start timestamptz NOT NULL,window_end timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('anomaly','no_anomaly','insufficient_data')),anomaly_score double precision,model_version text NOT NULL,schema_version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cow_id,window_end,model_version,schema_version));
CREATE INDEX ON ml_predictions(cow_id,window_end DESC);
CREATE TABLE alerts(id uuid PRIMARY KEY,cow_id text NOT NULL REFERENCES cows(id),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','acknowledged','resolved')),condition text NOT NULL DEFAULT 'telemetry_anomaly',prediction_id uuid NOT NULL REFERENCES ml_predictions(id),created_at timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX ON alerts(cow_id,condition) WHERE state != 'resolved';
CREATE TABLE alert_actions(id uuid PRIMARY KEY,alert_id uuid NOT NULL REFERENCES alerts(id),user_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
